// Signs release builds with Cairn's own upload key, when one is given.
//
// `android/` is generated by `expo prebuild` and Expo's template signs
// release builds with the debug key. Android only installs an update over an
// app signed with the same key, so every release published for people to
// install must be signed with one key, kept by the maintainer (see
// docs/release.md). This plugin appends a signing block to
// android/app/build.gradle that reads the key from the environment:
//
//   CAIRN_UPLOAD_STORE_FILE      absolute path to the .jks keystore
//   CAIRN_UPLOAD_STORE_PASSWORD
//   CAIRN_UPLOAD_KEY_ALIAS
//   CAIRN_UPLOAD_KEY_PASSWORD
//
// The release workflow sets them from GitHub secrets. Without them nothing
// changes, so a local `expo run:android --variant release` still works.

// pnpm's strict node_modules layout does not expose @expo/config-plugins to
// this package, so reach it the way Expo resolves its own dependencies.
function requireConfigPlugins() {
  try {
    return require('@expo/config-plugins');
  } catch (e) {
    return require(
      require.resolve('@expo/config-plugins', {
        paths: [require.resolve('expo/package.json', { paths: [__dirname] })],
      })
    );
  }
}

const { withAppBuildGradle } = requireConfigPlugins();

const MARKER_BEGIN = '// >>> cairn:release-signing (generated by plugins/withReleaseSigning.js)';
const MARKER_END = '// <<< cairn:release-signing';

const BLOCK = `
${MARKER_BEGIN}
// Release builds are signed with Cairn's upload key when the environment
// names one (the release workflow does); otherwise Expo's default stands.
// Edit the plugin, not this file, which the next \`expo prebuild\` rewrites.
def cairnStoreFile = System.getenv('CAIRN_UPLOAD_STORE_FILE')
if (cairnStoreFile) {
  android.signingConfigs.create('cairnRelease') {
    storeFile file(cairnStoreFile)
    storePassword System.getenv('CAIRN_UPLOAD_STORE_PASSWORD')
    keyAlias System.getenv('CAIRN_UPLOAD_KEY_ALIAS')
    keyPassword System.getenv('CAIRN_UPLOAD_KEY_PASSWORD')
  }
  android.buildTypes.release.signingConfig = android.signingConfigs.cairnRelease
}
${MARKER_END}
`;

function appendBlock(contents) {
  // Replace a block from an earlier prebuild rather than stacking another.
  const begin = contents.indexOf(MARKER_BEGIN);
  if (begin !== -1) {
    const end = contents.indexOf(MARKER_END, begin);
    contents =
      end === -1
        ? contents.slice(0, begin)
        : contents.slice(0, begin) + contents.slice(end + MARKER_END.length);
  }
  return contents.replace(/\s+$/, '') + '\n' + BLOCK;
}

const withReleaseSigning = (config) => {
  return withAppBuildGradle(config, (cfg) => {
    if (cfg.modResults.language !== 'groovy') {
      throw new Error(
        'withReleaseSigning: expected a Groovy app/build.gradle, got ' + cfg.modResults.language
      );
    }
    cfg.modResults.contents = appendBlock(cfg.modResults.contents);
    return cfg;
  });
};

module.exports = withReleaseSigning;
module.exports.appendBlock = appendBlock;
